public class OnClickDetector extends LayoutDetector {

    private static final Implementation IMPLEMENTATION = new Implementation(
            OnClickDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "OnClick",
            "onClick method does not exist",
            "The `onClick` attribute value should be the name of a method in this View's context to invoke when the view is clicked. ...",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            IMPLEMENTATION);

    @Override
    public Collection<String> getApplicableAttributes() {
        return Collections.singletonList(ATTR_ON_CLICK);
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        String value = attribute.getValue();
        if (value == null || value.isEmpty()) {
            return;
        }

        // The method name might be defined in a string resource
        ResourceUrl url = ResourceUrl.parse(value);
        if (url != null && url.type == ResourceType.STRING && !url.framework) {
            value = resolveStringResource(context, url);
            if (value == null || value.isEmpty()) {
                return;
            }
        }

        // Find the activity class specified by tools:context
        String className = findContextClassName(context, attribute.getOwnerElement());
        if (className == null) {
            return;
        }

        JavaEvaluator evaluator = context.getEvaluator();
        PsiClass cls = evaluator.findClass(className);
        if (cls == null) {
            return;
        }

        if (!hasOnClickMethod(evaluator, cls, value)) {
            context.report(ISSUE, attribute, context.getValueLocation(attribute),
                    String.format("Corresponding method handler '%1$s' not found", value));
        }
    }

    @Nullable
    private static String findContextClassName(@NonNull XmlContext context, @NonNull Element element) {
        Node node = element;
        while (node != null) {
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element el = (Element) node;
                String contextClass = el.getAttributeNS(TOOLS_URI, ATTR_CONTEXT);
                if (!contextClass.isEmpty()) {
                    if (contextClass.startsWith(".")) {
                        String pkg = context.getProject().getPackage();
                        if (pkg != null) {
                            return pkg + contextClass;
                        }
                    }
                    return contextClass;
                }
            }
            node = node.getParentNode();
        }
        return null;
    }

    private static boolean hasOnClickMethod(
            @NonNull JavaEvaluator evaluator,
            @NonNull PsiClass cls,
            @NonNull String name) {
        for (PsiMethod method : cls.findMethodsByName(name, true)) {
            if (!method.hasModifierProperty(PsiModifier.PUBLIC)
                    || method.hasModifierProperty(PsiModifier.STATIC)) {
                continue;
            }
            PsiParameterList parameterList = method.getParameterList();
            if (parameterList.getParametersCount() != 1) {
                continue;
            }
            PsiParameter parameter = parameterList.getParameters()[0];
            PsiClass paramClass = PsiUtil.resolveClassInClassTypeOnly(parameter.getType());
            if (paramClass != null
                    && evaluator.extendsClass(paramClass, SdkConstants.CLASS_VIEW, false)) {
                return true;
            }
        }
        return false;
    }

